<script>
(()=>{'use strict';const form=document.getElementById('exam-form'), cards=[...form.querySelectorAll('.question')],total=cards.length,overlay=document.getElementById('overlay');let submitted=false;const deadline=Date.parse(@json($deadline->toIso8601String())),offset=Date.parse(@json(now('Asia/Dhaka')->toIso8601String()))-Date.now();function counts(){const answered=cards.filter(c=>c.querySelector('input:checked')).length, remaining=total-answered;['answered','footer-answered','confirm-answered'].forEach(id=>document.getElementById(id).textContent=answered);['remaining','footer-remaining','confirm-remaining'].forEach(id=>document.getElementById(id).textContent=remaining);document.getElementById('progress').style.width=(total?answered*100/total:0)+'%'}form.addEventListener('change',counts);form.querySelectorAll('.clear').forEach(b=>b.addEventListener('click',()=>{b.closest('.question').querySelectorAll('input').forEach(i=>i.checked=false);counts()}));form.querySelectorAll('.next').forEach(b=>b.addEventListener('click',()=>{const c=b.closest('.question'),next=c.nextElementSibling;if(next){c.style.display='none';next.style.display='block';next.scrollIntoView({behavior:'smooth',block:'start'})}}));function send(){if(submitted)return;submitted=true;document.getElementById('confirm').disabled=true;form.submit()}document.getElementById('open-confirm').addEventListener('click',()=>{counts();overlay.classList.add('visible')});document.getElementById('cancel').addEventListener('click',()=>overlay.classList.remove('visible'));document.getElementById('confirm').addEventListener('click',send);function tick(){if(submitted)return;const sec=Math.max(0,Math.ceil((deadline-Date.now()-offset)/1000));document.getElementById('timer').textContent=sec?String(Math.floor(sec/60)).padStart(2,'0')+':'+String(sec%60).padStart(2,'0'):'সময় শেষ';if(sec===0)send()}tick();setInterval(tick,1000);window.addEventListener('beforeunload',e=>{if(!submitted){e.preventDefault();e.returnValue=''}})})();
</script></body></html>
